import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.jwovEGr5.js";const c=JSON.parse('{"title":"心肺复苏","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/新生体验/心肺复苏（实践）.md","filePath":"中山大学/新生体验/心肺复苏（实践）.md"}'),p={name:"中山大学/新生体验/心肺复苏（实践）.md"};function l(n,a,i,_,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="心肺复苏" tabindex="-1">心肺复苏 <a class="header-anchor" href="#心肺复苏" aria-label="Permalink to &quot;心肺复苏&quot;">​</a></h1><p>课程时间：2026.8.23 9:45~10:45</p><p>课程地点：中大南校区体育馆内</p><h2 id="活动主要内容" tabindex="-1">活动主要内容 <a class="header-anchor" href="#活动主要内容" aria-label="Permalink to &quot;活动主要内容&quot;">​</a></h2><p>使用假人具体讲解心肺复苏，同学们进行实操训练</p><p>注意要点：</p><h3 id="_1-先判断环境的危险程度-例如是不是在马路上、泥泞处" tabindex="-1">1. 先判断环境的危险程度（例如是不是在马路上、泥泞处） <a class="header-anchor" href="#_1-先判断环境的危险程度-例如是不是在马路上、泥泞处" aria-label="Permalink to &quot;1. 先判断环境的危险程度（例如是不是在马路上、泥泞处）&quot;">​</a></h3><h3 id="_2-判断人的情况" tabindex="-1">2. 判断人的情况 <a class="header-anchor" href="#_2-判断人的情况" aria-label="Permalink to &quot;2. 判断人的情况&quot;">​</a></h3><p>轻拍高呼，拍肩膀，两只耳朵都要叫一下（防止听力问题）</p><p>如果发现没有意识，进行下一步</p><h3 id="_3-触摸颈动脉-观察呼吸" tabindex="-1">3. 触摸颈动脉+观察呼吸 <a class="header-anchor" href="#_3-触摸颈动脉-观察呼吸" aria-label="Permalink to &quot;3. 触摸颈动脉+观察呼吸&quot;">​</a></h3><p>喉结向旁边2~3厘米有颈动脉，判断脉搏（8秒左右）</p><p>发现心脏骤停，没有脉搏，进行下一步</p><h3 id="_4-向周围人寻求帮助" tabindex="-1">4. 向周围人寻求帮助 <a class="header-anchor" href="#_4-向周围人寻求帮助" aria-label="Permalink to &quot;4. 向周围人寻求帮助&quot;">​</a></h3><p>让别人帮你打120、拿AED</p><blockquote><p>语言技巧：清楚点明某一个人，防止羊群效应（例如：那个戴帽子的先生）</p></blockquote><h3 id="_5-在aed来之前-进行心肺复苏" tabindex="-1">5. 在AED来之前，进行心肺复苏 <a class="header-anchor" href="#_5-在aed来之前-进行心肺复苏" aria-label="Permalink to &quot;5. 在AED来之前，进行心肺复苏&quot;">​</a></h3><p>30次按压+2次人工呼吸</p><p>人工呼吸前，将头部偏转，用比心的手势检查呼吸道有没有堵塞</p><p><strong>人工呼吸：</strong></p><p>一手压额头，另一手抬下颌（打开气道）</p><p>吹气时，压额头的手要捏住昏迷者的鼻子，吹完后松开鼻子</p><p>可以简单参考新生课程文章：<a href="../%E6%96%B0%E7%94%9F%E8%AF%BE%E7%A8%8B/%E5%BF%83%E8%82%BA%E5%A4%8D%E8%8B%8F" target="_blank">心肺复苏</a>。</p>',23)])])}const u=e(p,[["render",l]]);export{c as __pageData,u as default};
